"""Local title-filter correction, then the one unattempted PDF GET. No repeated index query."""
from pathlib import Path
import requests,json,hashlib,datetime,time,subprocess
O=Path(__file__).resolve().parent;sid='600050.SH';q=O/'sources'/(sid+'_index.json');x=json.loads(q.read_text());ledger=json.loads((O/'NETWORK_LEDGER.json').read_text());assert len(ledger)==7
rows=[r for r in x['api_response']['announcements'] if r['secCode']=='600050' and '2022年半年度现金红利实施公告' in r['announcementTitle']];assert len(rows)==1;a=rows[0];assert a['announcementId']=='1215000981';url='https://static.cninfo.com.cn/'+a['adjunctUrl'];assert not (O/'sources'/(sid+'.pdf')).exists()
def dump(n,o):(O/n).write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n')
def now():return datetime.datetime.now(datetime.timezone.utc).isoformat()
dump('LOCAL_TITLE_FILTER_CORRECTION.json',{'reason':'Original selector recognized 权益分派/利润分配/分红派息 but omitted 现金红利. The official index request succeeded and contains the precise notice.','original_stop_preserved':True,'index_retry':False,'selected_announcement_id':a['announcementId'],'pdf_get_previously_attempted':False,'remaining_http_budget':1});dump('sources/600050.SH_selected.json',a)
t=time.monotonic();r=requests.get(url,timeout=20);ledger.append({'url':url,'method':'GET','retrieved_utc':now(),'status':r.status_code,'elapsed_s':time.monotonic()-t,'bytes':len(r.content)});dump('NETWORK_LEDGER.json',ledger);r.raise_for_status();assert r.content.startswith(b'%PDF') and len(r.content)<10000000;p=O/'sources'/(sid+'.pdf');p.write_bytes(r.content);h=hashlib.sha256(r.content).hexdigest();dump('sources/'+sid+'.json',{'url':url,'metadata':a,'sha256':h,'retrieved_utc':now()})
script='ObjC.import("Foundation"); ObjC.import("PDFKit"); var d=$.PDFDocument.alloc.initWithURL($.NSURL.fileURLWithPath('+json.dumps(str(p))+')); var a=[]; for(var i=0;i<d.pageCount;i++){a.push({page:i+1,text:ObjC.unwrap(d.pageAtIndex(i).string)})}; JSON.stringify({pages:a});';proc=subprocess.run(['/usr/bin/osascript','-l','JavaScript','-e',script],capture_output=True,text=True,check=True,timeout=30);text=json.loads(proc.stdout);text.update(source_sha256=h,extraction_warning=proc.stderr.strip());dump('sources/'+sid+'.text.json',text)
protected=json.loads((O/'PROTECTED_INPUT_HASHES.json').read_text());assert all(hashlib.sha256(Path(p).read_bytes()).hexdigest()==v for p,v in protected.items());assert len(ledger)==8
dump('ACQUISITION_RESULT.json',{'new_requests':8,'new_pdf_events':4,'old_compound47_unchanged':True,'account_runs':0,'registered_events':0,'old_sources_written':False,'elapsed_http_seconds':sum(r['elapsed_s'] for r in ledger),'local_selector_error_recovered_using_same_index_response':True,'external_retry':False})
print(json.dumps({'sid':sid,'url':url,'sha256':h,'pages':len(text['pages'])},ensure_ascii=False));print('\n'.join('PAGE '+str(p['page'])+'\n'+p['text'] for p in text['pages']))
